 start(){const jokers=this.shuffle(D.cards.filter(c=>c.type==='joker').map(c=>c.id));this.excludedJokers=jokers.slice(2);const selected=new Set(jokers.slice(0,2)),plain=this.shuffle(D.cards.filter(c=>c.type!=='instant'&&(c.type!=='joker'||selected.has(c.id))).map(c=>c.id));for(let i=0;i<5;i++)for(const p of this.players)p.hand.push(plain.pop());this.matchSetup=matchSetup.build([...plain,...D.cards.filter(c=>c.type==='instant'&&c.effect!=='bloodpact').map(c=>c.id)],D,this.rng);this.excludedInstants=[...this.matchSetup.replaced,...(this.matchSetup.bloodPactsIncluded?[]:matchSetup.config.bloodPact.ids)];this.deck=this.shuffle(this.matchSetup.deck);this.turn=Math.floor(this.rng()*4);this.phase='turn';this.log=[`Five private cards dealt. ${this.players[this.turn].name} goes first. Two mystery Jokers and eight Instants are in play.`];this.rememberTurn();return this;}
 rememberTurn(){const keys=['players','deck','discard','table','turn','round','used','phase','log','ended','endPending','result','serial','reaperHearts','removed','endCurrentTurn','excludedJokers','excludedInstants','lockdownTurns','legendaryUsed','drawOnly','knownTop','sunLocation','copiedForesight'];const state={};for(const k of keys)if(this[k]!==undefined)state[k]=this[k];this.turnHistory[this.turn].push({sequence:++this.historySequence,state:JSON.parse(JSON.stringify(state))});this.turnHistory[this.turn]=this.turnHistory[this.turn].slice(-2);}
 async next(){await super.next();if(!this.ended)this.rememberTurn();}
 botActionPublic(p){const move=super.botActionPublic(p);if(move)return move;const id=p.hand.find(x=>this.card(x)?.effect==='rewind'),previous=this.turnHistory[p.id].at(-2)?.state.players[p.id];return id&&previous&&this.legal(p,id)&&previous.hearts>p.hearts?id:null;}
