CurrentGame.prototype.effect=async function(p,id,ctx={}){const previous=this.crocContext,context={actor:p.id,targets:new Map()};this.crocContext=context;let result;try{if(this.card(id).effect==='gluttonyJack'){const affected=this.living().filter(q=>q.hand.length>=10);for(const q of affected){const selected=[];for(let i=0;i<3;i++)selected.push(await this.chooseCard(q,'Choose card '+(i+1)+' of 3 to remove',q.hand.filter(x=>!selected.includes(x))));const legends=selected.filter(x=>this.isLegend(x));for(const x of selected.filter(x=>!this.isLegend(x))){q.hand.splice(q.hand.indexOf(x),1);this.discard.push(x);}if(legends.length)await this.returnCards(q,legends);await this.say(q.name+' removes 3 cards for Gluttony’s Curse.');}}else result=await beforeCrocEffect.call(this,p,id,ctx);}finally{this.crocContext=previous;}for(const [pid,card] of context.targets){const q=this.players[pid];if(!q.alive||!q.hand.includes(card))continue;q.hand.splice(q.hand.indexOf(card),1);const item=await this.reveal(q,card,'automatically triggers');if(card!=='Joker crocodile')await this.transformCopy(q,card,'Joker crocodile');p.legendaryCursed=true;if(card!=='Joker crocodile')await this.transformCopy(q,card,null);await this.park(item,'removed');await this.say(p.name+' cannot play Legendary Cards for the rest of the game.');}return result;};

