CurrentGame.prototype.legal=function(p,id){const c=this.card(id);if(!['rankcopy','exactcopy'].includes(c?.effect))return copyBaseLegal.call(this,p,id);if(!p.alive||this.ended||this.drawOnly||!p.hand.includes(id)||p.ward?.angel===id||p.legendaryCursed||this.lockdownTurns||p.effects.some(e=>this.effectType(e)==='sacrifice'))return false;return this.copyChoices(p,id).length>0;};
