CurrentGame.prototype.rewindMoves=function(saved,rewind){const zones=state=>{const map=new Map();for(const id of state.deck)map.set(id,{zone:'deck',public:false});for(const id of state.discard)map.set(id,{zone:'discard',public:true});for(const id of state.removed)map.set(id,{zone:'removed',public:true});for(const t of state.table)map.set(t.card,{zone:'discard',public:true});for(const p of state.players){for(const id of p.hand)map.set(id,{zone:'hand',player:p.id,public:p.id===0||p.revealed?.includes(id)});for(const t of p.effects)map.set(t.card,{zone:'effect',player:p.id,public:true});if(p.ward)map.set(p.ward.card,{zone:'effect',player:p.id,public:false});}return map;};const before=zones(this),after=zones(saved),moves=[];for(const [id,to] of after){const from=before.get(id);if(id===rewind||!from||from.zone===to.zone&&from.player===to.player)continue;moves.push({card:from.public&&to.public?id:null,back:this.card(id).back,from:{zone:from.zone,player:from.player},to:{zone:to.zone,player:to.player}});}return moves;};


const agreedPark=CurrentGame.prototype.park,agreedReturns=CurrentGame.prototype.returnCards,agreedChoosePlayer=CurrentGame.prototype.choosePlayer,agreedEffect=CurrentGame.prototype.effect;
CurrentGame.prototype.park=async function(item,...args){await agreedPark.call(this,item,...args);for(const response of item.afterDiscard||[])await this.park(response);};
CurrentGame.prototype.returnCards=async function(p,ids,ctx={}){const basics=ids.filter(id=>p.hand.includes(id)&&!this.isLegend(id)&&!(ctx.specialReturn&&this.card(id).back==='purple'));for(const id of basics){p.hand.splice(p.hand.indexOf(id),1);this.discard.push(id);}return agreedReturns.call(this,p,ids.filter(id=>this.isLegend(id)||(ctx.specialReturn&&this.card(id).back==='purple')),ctx);};
CurrentGame.prototype.choosePlayer=async function(p,...args){return agreedChoosePlayer.call(this,p,...args);};
CurrentGame.prototype.legendary=async function(p,id,ctx={}){ctx.prior??=this.discard.at(-1);let source=id;const copy=this.card(id).effect;if(['rankcopy','exactcopy','wildcard'].includes(copy)&&!ctx.returning&&!ctx.instant){let choices=copy==='wildcard'?D.cards.filter(c=>['utility','heart'].includes(c.type)&&this.copySourceLegal(p,id,c.id)).map(c=>c.id):this.copyChoices(p,id,ctx.prior);source=copy==='exactcopy'?choices[0]:await this.chooseCard(p,this.card(id).name+': choose an effect',choices);ctx.selectedCopy=source;if(this.card(source)?.effect==='wildcard'){source=await this.chooseCard(p,'Wildcard: choose an effect',D.cards.filter(c=>['utility','heart'].includes(c.type)&&this.copySourceLegal(p,id,c.id)).map(c=>c.id));ctx.selectedCopy=source;}}
 const c=this.card(source),effect=c?.effect,targets=['upper','mind','puppet','thief','pull','lights','trade','steal','peek','swap','shuffle','skip','exchange','stealheart','mutual','pass','revealhand'];if(effect==='pass'){const effects=p.effects.filter(e=>this.passTargets(p,e).length);ctx.passCard=await this.chooseCard(p,'Choose the effect to pass',effects.map(e=>e.card));}if(targets.includes(effect)){const self=['pull','lights','shuffle','skip','revealhand'].includes(effect);let opts=this.living().filter(q=>(self||q.id!==p.id)&&(effect!=='steal'||q.hand.length>0)&&(effect!=='exchange'||Math.min(p.max,q.hearts)>p.hearts)&&(effect!=='stealheart'||q.hearts>=2)&&(effect!=='mutual'||q.hearts<q.max)&&(effect!=='pass'||this.passTargets(p,p.effects.find(e=>e.card===ctx.passCard)).some(t=>t.id===q.id)));ctx.target=await this.choose(p,'Choose a player for '+c.name,opts.map(q=>({value:q.id,label:q.name,hearts:q.hearts,count:q.hand.length})),{kind:'player'});}
 const item=await this.reveal(p,id);if(ctx.target!=null){item.target=ctx.target;await this.say(p.name+' targets '+this.players[ctx.target].name+' with '+c.name+'.');}const response=await this.reaction(p,id);if(response.kind==='hijack'){this.players[response.player].hand.push(id);await this.park(item,'hand',response.player);return false;}if(response.kind==='cancel'){await this.park(item);return false;}const placed=await this.effect(p,id,ctx);await this.park(item,placed?.where||'discard',placed?.target);return true;};
CurrentGame.prototype.effect=async function(p,id,ctx={}){const previous=this.targetPlan;if(ctx.target!=null&&!this.targetPlan)this.targetPlan={actor:p.id,target:ctx.target,passCard:ctx.passCard,used:false};try{if(this.card(id).effect==='magician')this.used++;if(this.card(id).effect==='revealhand'){const target=await this.choosePlayer(p,'Whose Legendaries will you reveal?',true);if(target!==null){const q=this.players[target];q.revealed=[...new Set([...q.revealed,...this.legendaries(q)])];await this.say(q.name+' reveals their current hand Legendaries.');}return null;}if(ctx.selectedCopy&&['rankcopy','exactcopy','wildcard'].includes(this.card(id).effect)){if(this.card(ctx.selectedCopy).effect==='pandora')this.copiedPandora=true;return await this.copyEffect(p,id,ctx.selectedCopy,{...ctx,selectedCopy:undefined});}return await agreedEffect.call(this,p,id,ctx);}finally{this.targetPlan=previous;}};

CurrentGame.prototype.bloodPartner=function(p){if(!p.alive||!p.effects.some(e=>this.effectType(e)==='bloodpact'))return null;return this.players.find(q=>q.id!==p.id&&q.alive&&q.effects.some(e=>this.effectType(e)==='bloodpact'))||null;};
const pactDamage=CurrentGame.prototype.damage,pactDie=CurrentGame.prototype.die;
